    [Theory]
    [InlineData(0)]
    [InlineData(1)]
    [InlineData(2)]
    [InlineData(3)]
    [InlineData(4)]
    [InlineData(5)]
    [InlineData(6)]
    [InlineData(7)]
    [InlineData(8)]
    [InlineData(9)]
    public void CompleteProfilesMatchThePinnedNativeGammaBranch(int fixtureIndex)
    {
        NativeFixture fixture = NativeFixtures[fixtureIndex];
        foreach (bool rec2020 in new[] { false, true })
        {
            byte[] profile = Create(rec2020, fixture.Gamma);
            Assert.Equal(fixture.Size, profile.Length);
            Assert.Equal(rec2020 ? fixture.Rec2020Sha256 : fixture.P3Sha256,
                Convert.ToHexString(SHA256.HashData(profile)));
            Assert.Equal(rec2020 ? fixture.Rec2020Id : fixture.P3Id, Convert.ToHexString(profile.AsSpan(84, 16)));
            Dictionary<string, Tag> tags = Tags(profile);
            Assert.Equal((rec2020 ? "RGB_D65_202_Per_g" : "RGB_D65_DCI_Per_g") + fixture.Suffix,
                Text(profile, tags["desc"]));
            Assert.Equal(fixture.FixedExponent, Int32(profile, tags["rTRC"].Offset + 12));
        }
    }

    [Theory]
    [InlineData(false, 1, "1", 492)]
    [InlineData(true, 1, "1", 492)]
    [InlineData(false, 2.2, "0.454545", 508)]
    [InlineData(true, 2.2, "0.454545", 508)]
    [InlineData(false, 2.6, "0.384615", 508)]
    [InlineData(true, 2.6, "0.384615", 508)]
    [InlineData(false, 8192, "0.00012207", 512)]
    [InlineData(true, 8192, "0.00012207", 512)]
    public void HeaderAndAlignedTagsDescribeTheRequestedWideGamutAndGenericGamma(
        bool rec2020, double gamma, string suffix, int size)
    {
        byte[] profile = Create(rec2020, gamma);
        Assert.Equal(size, profile.Length);
        Assert.Equal(profile.Length, Int32(profile, 0));
        Assert.Equal("jxl ", Signature(profile, 4));
        Assert.Equal(0x04400000, Int32(profile, 8));
        Assert.Equal("mntr", Signature(profile, 12));
        Assert.Equal("RGB ", Signature(profile, 16));
        Assert.Equal("XYZ ", Signature(profile, 20));
        Assert.Equal(new[] { 2019, 12, 1, 0, 0, 0 },
            Enumerable.Range(0, 6).Select(index => UInt16(profile, 24 + index * 2)));
        Assert.Equal("acsp", Signature(profile, 36));
        Assert.Equal("APPL", Signature(profile, 40));
        Assert.All(profile[44..68], value => Assert.Equal(0, value));
        Assert.Equal(new[] { 0x0000f6d6, 0x00010000, 0x0000d32d },
            Enumerable.Range(0, 3).Select(index => Int32(profile, 68 + index * 4)));
        Assert.Equal("jxl ", Signature(profile, 80));
        Assert.All(profile[100..128], value => Assert.Equal(0, value));

        Dictionary<string, Tag> tags = Tags(profile);
        Assert.Equal(new[] { "desc", "cprt", "wtpt", "chad", "rXYZ", "gXYZ", "bXYZ", "rTRC", "gTRC", "bTRC" },
            tags.Keys);
        // Upstream spells P3's primaries token DCI even with a D65 white.
        Assert.Equal((rec2020 ? "RGB_D65_202_Per_g" : "RGB_D65_DCI_Per_g") + suffix,
            Text(profile, tags["desc"]));
        Assert.Equal("CC0", Text(profile, tags["cprt"]));
        Assert.Equal(2, IccProfile.LookupTransferFunction(profile, TestContext.Current.CancellationToken));
        Tag white = tags["wtpt"];
        Assert.Equal("XYZ ", Signature(profile, white.Offset));
        Assert.Equal(20, white.Length);
        double[] expectedWhite = [0.964203, 1, 0.824905];
        for (int channel = 0; channel < 3; channel++)
            AssertClose(expectedWhite[channel], Fixed(profile, white.Offset + 8 + channel * 4),
                0.5 / 65536, $"media white channel {channel}");
        Assert.Equal("sf32", Signature(profile, tags["chad"].Offset));
        Assert.Equal(44, tags["chad"].Length);
        foreach (string color in new[] { "r", "g", "b" })
        {
            Assert.Equal("XYZ ", Signature(profile, tags[color + "XYZ"].Offset));
            Assert.Equal(20, tags[color + "XYZ"].Length);
        }
    }

    [Fact]
    public void DescriptionsAndProfileIdsAreIndependentOfTheCurrentCulture()
    {
        byte[][] expected = [Create(false, 2.2), Create(true, 2.2)];
        CultureInfo original = CultureInfo.CurrentCulture;
        try
        {
            CultureInfo.CurrentCulture = CultureInfo.GetCultureInfo("fr-FR");
            Assert.Equal(expected[0], Create(false, 2.2));
            Assert.Equal(expected[1], Create(true, 2.2));
        }
        finally
        {
            CultureInfo.CurrentCulture = original;
        }
    }

    [Theory]
    [InlineData(double.NaN)]
